/** The set id: changes whenever any vector changes (scripts/check-api-sync.mjs reads it). */
export const GOLDEN_VECTOR_SET_ID = "python-traceback-explainer-golden-2026-10-27b"; // "b": the share vectors added later the same day

/** An expected exception, in the shape shape() gives the engine's output. */
export interface ExpExc {
  /** The exception line as printed ("" for a block cut before it, "..." for a group past max_group_depth). */
  line: string;
  /** The lines after it. */
  extra?: string[];
  /** The banner after it. */
  link?: "cause" | "context";
  /** The frames: "file:line:function", the first source line, the kind, repeats, the marked span and locals. */
  frames?: { at: string; src: string | null; kind: string; repeated?: number; mark?: string; locals?: number }[];
  /** The SyntaxError location: "file:line:column". */
  location?: string;
  /** The members of a group, each a chain. */
  members?: ExpExc[][];
  /** Members not printed ("and N more exceptions"). */
  more?: number;
}

/** A traceback vector. */
export interface TracebackVector {
  /** Stable name. */
  id: string;
  /** What printed the input, and how. */
  ran: string;
  /** The input, byte for byte. */
  input: string;
  /** The expected chain. */
  chain: ExpExc[];
  /** Where to look first: "exc:kind:frame:innerKind", with "<exc:link:kind:frame:innerKind" for the earlier one. */
  look: string[];
  /** The release range the evidence allows: [min, max] minor numbers, null when open. */
  release: [number | null, number | null];
  /** The note codes, sorted. */
  notes: string[];
  /** The sensitive findings' rules, in paste order. */
  sensitive: string[];
  /** CPython's suggestions: "kind:value". */
  suggestions?: string[];
  /** errno and its text: "errno:text". */
  oserror?: string;
  /** Codec details: "codec|what|position|reason". */
  codec?: string;
  /** The hint id. */
  hint?: string;
  /** The exact redacted copy, when pinned. */
  redacted?: string;
}

/** A refusal vector. */
export interface RefusalVector { id: string; what: string; input: string | (() => string); code: string; notes: string[] }

