// ---------------------------------------------------------------------------
// Verification
// ---------------------------------------------------------------------------

/**
 * JSON with object keys sorted, so two values compare equal whatever order their keys were written in.
 * @param x any JSON value
 * @returns the canonical text
 */
function canon(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map(canon).join(",")}]`; // arrays keep their order
  if (x && typeof x === "object") return `{${Object.keys(x as object).sort().map((k) => `${JSON.stringify(k)}:${canon((x as Record<string, unknown>)[k])}`).join(",")}}`; // keys sorted
  return JSON.stringify(x); // a primitive
} // canon

/**
 * The engine's chain in the shape of the expectations.
 * @param chain a chain
 * @returns the expected-shape chain
 */
export function shape(chain: ChainItem[]): ExpExc[] {
  return chain.map((it) => { // each exception
    const e = it.exc; // the node
    const line = e.depthLimited !== null ? "..." : e.type === null ? "" : e.type + (e.message !== null ? `: ${e.message}` : ""); // the exception line
    const out: ExpExc = { line }; // the shape
    if (e.extra.length) out.extra = e.extra; // lines after it
    if (it.link) out.link = it.link; // the banner after it
    if (e.frames.length) out.frames = e.frames.map((f) => { // each frame
      const fr: NonNullable<ExpExc["frames"]>[number] = { at: `${f.file}:${f.lineno}:${f.func}`, src: f.source.length ? f.source[0].trim() : null, kind: f.kind }; // identity
      if (f.repeated) fr.repeated = f.repeated; // collapsed repeats
      if (f.mark) fr.mark = (f.mark.lines === 1 ? `${f.mark.start}-${f.mark.end}` : `${f.mark.start}+${f.mark.lines}`) + (f.mark.focusKind ? `~${f.mark.focusKind}` : ""); // the marked span
      if (f.locals.length) fr.locals = f.locals.length; // local variables
      return fr; // the frame
    }); // frames
    if (e.location) out.location = `${e.location.file}:${e.location.lineno}:${e.location.column}`; // the SyntaxError location
    if (e.group) { out.members = e.group.members.map(shape); if (e.group.more) out.more = e.group.more; } // members
    return out; // the exception
  }); // chain
} // shape

/**
 * A FirstLook in the compact form of the expectations.
 * @param f the reading
 * @returns "exc:kind:frame:innerKind" with "<exc:link:kind:frame:innerKind" when an earlier exception is linked
 */
export function lookString(f: FirstLook): string {
  const one = (x: FirstLook): string => `${x.exc}:${x.kind}:${x.frame ?? "-"}:${x.innerKind ?? "-"}`; // one reading
  return one(f) + (f.previous ? `<${f.previous.exc}:${f.previous.link}:${one(f.previous.look).split(":").slice(1).join(":")}` : ""); // with the earlier one
} // lookString

/**
 * Run every vector.
 * @returns the set id, the number of checks, how many passed, and the failures
 */
/** A share vector: a paste and what a "Share results" link carries, or why it carries nothing. */
export interface ShareVector { id: string; input: string; text: string | null; findings?: number; reason?: "no-reading" | "secrets-skipped"; skipped?: number }

/** The secrets vector's input and its hand-written redacted copy (TRACEBACK_VECTORS "secrets"). */
const SECRETS_VECTOR = (): { input: string; redacted: string } => { const v = TRACEBACK_VECTORS.find((x) => x.id === "secrets"); return { input: v?.input ?? "", redacted: v?.redacted ?? "" }; }; // looked up once used
/** The Windows path vector's input and its redacted copy. */
const WINDOWS_VECTOR = (): { input: string; redacted: string } => { const v = TRACEBACK_VECTORS.find((x) => x.id === "windows-path"); return { input: v?.input ?? "", redacted: v?.redacted ?? "" }; }; // looked up once used

/** What Share results carries (2026-10-27): the redacted copy, never the paste; nothing when lines went unchecked. */
export const SHARE_VECTORS: readonly ShareVector[] = [
  { id: "share-example", input: EXAMPLE_TRACEBACK, text: EXAMPLE_TRACEBACK.split("/home/ana/").join("/home/<user>/"), findings: 1 }, // the user name in every path, one finding
  { id: "share-secrets", input: SECRETS_VECTOR().input, text: SECRETS_VECTOR().redacted, findings: 4 }, // a home directory, a JSON Web Token in a Bearer header, a password in a URL twice: the hand-written copy
  { id: "share-windows", input: WINDOWS_VECTOR().input, text: WINDOWS_VECTOR().redacted, findings: 1 }, // C:\Users\<name>\
  { id: "share-long-line-blocked", input: "Traceback (most recent call last):\n  File \"/home/ana/x.py\", line 1, in <module>\n    f(\"" + "a".repeat(2100) + "\")\nValueError: token=abc123secretdemo\n", text: null, reason: "secrets-skipped", skipped: 1 }, // a 2,107-character line the check did not read
  { id: "share-not-a-traceback", input: "hello world", text: null, reason: "no-reading" }, // refused: nothing to share
  { id: "share-empty", input: "", text: null, reason: "no-reading" }, // nothing pasted
];

export function verifyVectors(): { setId: string; total: number; passed: number; failures: string[] } {
  const failures: string[] = []; // what failed
  let total = 0; // checks run
  /** Compare one value. */
  const check = (id: string, what: string, got: unknown, want: unknown): void => {
    total += 1; // one more check
    if (canon(got) !== canon(want)) failures.push(`${id}: ${what}: got ${canon(got)}, want ${canon(want)}`); // a failure
  }; // check
  for (const v of TRACEBACK_VECTORS) { // the tracebacks
    const r: TracebackResult = explainTraceback(v.input); // the engine
    check(v.id, "ok", r.ok, true); // read
    if (!r.ok) continue; // nothing more to compare
    check(v.id, "chain", shape(r.chain), v.chain); // the structure
    check(v.id, "look", r.firstLook.map(lookString), v.look); // where to look first
    check(v.id, "release", [r.release.min, r.release.max], v.release); // the release range
    check(v.id, "notes", r.notes.map((n) => n.code).sort(), v.notes); // the notes
    check(v.id, "sensitive", r.sensitive.map((s) => s.rule), v.sensitive); // the findings
    const last = r.chain[r.chain.length - 1].exc; // the final exception
    if (v.suggestions) check(v.id, "suggestions", last.suggestions.map((s) => `${s.kind}:${s.value}`), v.suggestions); // CPython's own
    if (v.oserror) check(v.id, "oserror", last.oserror ? `${last.oserror.errno}:${last.oserror.text}` : null, v.oserror); // errno
    if (v.codec) check(v.id, "codec", last.codec ? `${last.codec.codec}|${last.codec.what}|${last.codec.position}|${last.codec.reason}` : null, v.codec); // codec details
    if (v.hint) check(v.id, "hint", last.hint, v.hint); // the hint
    if (v.redacted !== undefined) check(v.id, "redacted", r.redacted, v.redacted); // the redacted copy
    check(v.id, "deterministic", canon(explainTraceback(v.input)), canon(r)); // the same reading twice
  } // tracebacks
  for (const v of REFUSAL_VECTORS) { // the refusals
    const r = explainTraceback(typeof v.input === "function" ? v.input() : v.input); // the engine
    check(v.id, "refused", r.ok ? null : r.error?.code, v.code); // the code
    check(v.id, "notes", r.notes.map((n) => n.code).sort(), v.notes); // the notes
  } // refusals
  for (const [cp, w] of WIDTH_VECTORS) check(`width-${cp.toString(16)}`, "columns", columnsOf(cp), w); // widths
  for (const [name, chain] of TABLE_VECTORS) check(`table-${name}`, "chain", KNOWN_EXCEPTIONS.get(name)?.chain ?? null, chain); // the table
  check("example", "the Example is the example-poll vector's input", TRACEBACK_VECTORS.find((v) => v.id === "example-poll")?.input, EXAMPLE_TRACEBACK); // D-83
  for (const v of SHARE_VECTORS) { // Share results
    const s = shareableTraceback(v.input); // the derived form
    if (v.text === null) { check(v.id, "refused", s.ok ? "ok" : s.reason, v.reason); if (!s.ok && s.reason === "secrets-skipped") check(v.id, "skipped", s.skipped, v.skipped); continue; } // nothing to share
    check(v.id, "text", s.ok ? s.text : null, v.text); // byte for byte
    check(v.id, "findings", s.ok ? s.findings : null, v.findings); // what it hides
    check(v.id, "never the paste", s.ok && (v.findings ?? 0) > 0 ? s.text !== v.input : true, true); // a paste with findings never travels as typed
  } // share vectors
  return { setId: GOLDEN_VECTOR_SET_ID, total, passed: total - failures.length, failures }; // the report
} // verifyVectors

/** How many vectors the set holds (the manifest's goldenVectorCount). */
export const GOLDEN_VECTOR_COUNT = TRACEBACK_VECTORS.length + REFUSAL_VECTORS.length + WIDTH_VECTORS.length + TABLE_VECTORS.length + SHARE_VECTORS.length; // every vector (the share vectors since 2026-10-27)
